package main
import("bytes";"crypto/sha256";"encoding/csv";"encoding/hex";"encoding/json";"fmt";"io";"os";"path/filepath";"reflect";"strconv";"strings")
const history_max_bytes=64<<20
type history_timing struct{Kind string `json:"kind"`;Source string `json:"source_id"`;Input string `json:"input_sha256"`;Marker string `json:"marker_sha256"`;Frames int `json:"native_frames"`;Stride int `json:"native_stride"`;Upper int `json:"final_event_upper_native"`;Guard int `json:"guard_native"`;Start int `json:"final_post_start_native"`;Evidence string `json:"evidence_path"`;EvidenceHash string `json:"evidence_sha256"`}
type history_trace struct{kind,hash string; values map[string][]float64}
var history_profiles=map[string][2]int{"held-n32-tl32-00-32":{32,0},"held-n32-tl32-32-32":{32,32},"held-n01-tl32-00-32":{1,0},"held-n01-tl32-32-32":{1,32},"held-n32-tl32-40-32":{32,40},"held-n01-tl32-40-32":{1,40}}
func history_hash(data []byte)string{sum:=sha256.Sum256(data);return hex.EncodeToString(sum[:])}
func history_read(path string)([]byte,error){file,err:=os.Open(path);if err!=nil{return nil,err};defer file.Close();data,err:=io.ReadAll(io.LimitReader(file,history_max_bytes+1));if err!=nil{return nil,err};if len(data)>history_max_bytes{return nil,fmt.Errorf("input exceeds64MiB")};return data,nil}
func history_hash_file_must(path string)string{data,err:=history_read(path);if err!=nil{panic(err)};return history_hash(data)}
func history_json(data []byte,out interface{})error{if err:=history_unique_json(data);err!=nil{return err};decoder:=json.NewDecoder(bytes.NewReader(data));decoder.DisallowUnknownFields();if err:=decoder.Decode(out);err!=nil{return err};if err:=decoder.Decode(new(interface{}));err!=io.EOF{return fmt.Errorf("trailing JSON")};return nil}
func history_unique_json(data []byte)error{decoder:=json.NewDecoder(bytes.NewReader(data));var walk func()error;walk=func()error{token,err:=decoder.Token();if err!=nil{return err};delimiter,ok:=token.(json.Delim);if !ok{return nil};if delimiter=='{'{seen:=map[string]bool{};for decoder.More(){key,err:=decoder.Token();if err!=nil{return err};name,ok:=key.(string);if !ok||seen[name]{return fmt.Errorf("duplicate or invalid JSON key")};seen[name]=true;if err=walk();err!=nil{return err}}}else if delimiter=='['{for decoder.More(){if err=walk();err!=nil{return err}}}else{return fmt.Errorf("unexpected JSON delimiter")};_,err=decoder.Token();return err};if err:=walk();err!=nil{return err};if _,err:=decoder.Token();err!=io.EOF{return fmt.Errorf("trailing JSON")};return nil}
func history_integer(s string)(int64,error){if s==""||strings.TrimSpace(s)!=s{return 0,fmt.Errorf("invalid integer %q",s)};return strconv.ParseInt(s,10,64)}
func history_pcm(s string)(float64,error){v,err:=history_integer(s);if err!=nil||v< -32768||v>32767{return 0,fmt.Errorf("invalid signed16 PCM %q",s)};return float64(v),nil}
func history_trace_read(path string)(history_trace,error){r:=history_trace{values:map[string][]float64{}};data,err:=history_read(path);if err!=nil{return r,err};r.hash=history_hash(data);reader:=csv.NewReader(bytes.NewReader(data));header,err:=reader.Read();if err!=nil{return r,err};headers:=map[string][]string{"jt51":{"sample","left","right","xleft","xright","clock","status"},"opm":{"sample","left","right","clock","inc0","inc8","inc16","inc24","phase24"},"physical":{"sample","raw16_hex","linear"},"independent_synthetic":{"sample","left","right"}};for kind,want:=range headers{if reflect.DeepEqual(header,want){r.kind=kind}};if r.kind==""{return r,fmt.Errorf("unrecognized exact CSV schema")};for _,name:=range header{if name=="left"||name=="right"||name=="xleft"||name=="xright"||name=="linear"{r.values[name]=[]float64{}}};previous_clock:=int64(0);for n:=0;;n++{row,e:=reader.Read();if e==io.EOF{if n!=16384{return r,fmt.Errorf("CSV row count %d !=16384",n)};break};if e!=nil{return r,e};if n>=16384{return r,fmt.Errorf("too many CSV rows")};sample,e:=history_integer(row[0]);if e!=nil||sample!=int64(n){return r,fmt.Errorf("nonconsecutive sample at row%d",n)};for col,name:=range header{if _,ok:=r.values[name];ok{v,e:=history_pcm(row[col]);if e!=nil{return r,e};r.values[name]=append(r.values[name],v)}else if name!="sample"&&name!="raw16_hex"{v,e:=history_integer(row[col]);if e!=nil||v<0{return r,fmt.Errorf("invalid auxiliary integer %s",name)};if name=="clock"{if n>0&&(v<previous_clock||v-previous_clock!=64){return r,fmt.Errorf("clock cadence !=64")};previous_clock=v}}};if r.kind=="physical"{s:=row[1];if strings.HasPrefix(s,"0x"){s=s[2:]};if len(s)<1||len(s)>4||strings.TrimSpace(s)!=s{return r,fmt.Errorf("invalid raw16 hex")};for _,ch:=range s{if !strings.ContainsRune("0123456789abcdefABCDEF",ch){return r,fmt.Errorf("invalid raw16 hex digit")}};word,e:=strconv.ParseUint(s,16,16);if e!=nil{return r,e};exponent:=word>>13;if exponent<1||exponent>7{return r,fmt.Errorf("invalid raw exponent")};decoded:=int64((word>>3)&1023)-512;decoded<<=uint(exponent-1);if float64(decoded)!=r.values["linear"][n]{return r,fmt.Errorf("raw/linear mismatch")}}};return r,nil}
func(job *history_job)load()error{if _,ok:=history_profiles[job.profile];!ok{return fmt.Errorf("unknown profile")};method,err:=history_read(job.method_path);if err!=nil{return err};if history_hash(method)!=history_method_sha{return fmt.Errorf("method hash mismatch")};right,err:=history_trace_read(job.input);if err!=nil{return err};if job.marker==""{job.marker=job.input};left:=right;if job.marker!=job.input{left,err=history_trace_read(job.marker);if err!=nil{return err}};if right.kind=="physical"&&job.marker==job.input{return fmt.Errorf("physical input requires separate RIGHT and LEFT CSV")};var ok bool;job.right,ok=right.values[job.column];if !ok{return fmt.Errorf("missing selected RIGHT column")};job.left,ok=left.values[job.marker_column];if !ok{return fmt.Errorf("missing selected LEFT column")};if job.column=="left"||job.marker_column=="right"||job.column=="xleft"||job.column=="xright"||job.marker_column=="xleft"||job.marker_column=="xright"{return fmt.Errorf("RIGHT/LEFT role selection invalid")};if right.kind!=left.kind{return fmt.Errorf("mixed CSV schema kinds")};data,err:=history_read(job.timing_path);if err!=nil{return err};if err=history_json(data,&job.timing);err!=nil{return err};var keys map[string]json.RawMessage;if err=json.Unmarshal(data,&keys);err!=nil{return err};if len(keys)!=11{return fmt.Errorf("timing requires all11 binding fields")};t:=job.timing;if t.Source==""||t.Frames!=16384||t.Stride!=1||t.Guard!=128||t.Upper<0||t.Upper>int(^uint(0)>>1)-128||t.Start!=t.Upper+128{return fmt.Errorf("invalid timing geometry/source")};kind:=map[string]string{"independent_synthetic":"independent_synthetic","jt51":"public_model_sidecar","opm":"public_model_sidecar","physical":"physical_host_upper"}[right.kind];if t.Kind!=kind{return fmt.Errorf("timing kind/schema mismatch")};if t.Input!=right.hash||t.Marker!=left.hash{return fmt.Errorf("trace hash mismatch")};evidence:=t.Evidence;if !filepath.IsAbs(evidence){evidence=filepath.Join(filepath.Dir(job.timing_path),evidence)};proof,err:=history_read(evidence);if err!=nil{return err};if history_hash(proof)!=t.EvidenceHash{return fmt.Errorf("evidence hash mismatch")};exe,err:=os.Executable();if err!=nil{return err};job.binding=map[string]interface{}{"input":map[string]string{"path":job.input,"sha256":right.hash},"marker":map[string]string{"path":job.marker,"sha256":left.hash},"timing":map[string]string{"path":job.timing_path,"sha256":history_hash(data)},"evidence":map[string]string{"path":evidence,"sha256":t.EvidenceHash},"method_sha256":history_method_sha,"executable_sha256":history_hash_file_must(exe),"schema":right.kind};return nil}
func history_fresh_paths(paths []string)error{seen:=map[string]bool{};for _,path:=range paths{absolute,err:=filepath.Abs(path);if err!=nil{return err};if seen[absolute]{return fmt.Errorf("duplicate output path")};seen[absolute]=true;if _,err=os.Lstat(path);err==nil{return fmt.Errorf("output exists: %s",path)}else if !os.IsNotExist(err){return err};parent,err:=os.Stat(filepath.Dir(path));if err!=nil||!parent.IsDir(){return fmt.Errorf("output parent missing")}};return nil}
func history_write_exclusive(path string,data []byte)error{file,err:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0644);if err!=nil{return err};_,err=file.Write(data);close_err:=file.Close();if err!=nil{return err};return close_err}
